CREATE TABLE `login_attempts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `attempt_type` enum('ADMIN_LOGIN','CUSTOMER_LOGIN','REFRESH_TOKEN') NOT NULL,
  `attempted_at` datetime(6) NOT NULL,
  `email_or_mobile` varchar(180) DEFAULT NULL,
  `ip_address` varchar(80) DEFAULT NULL,
  `success` bit(1) NOT NULL,
  `user_agent` varchar(500) DEFAULT NULL,
  `user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_login_attempts_user` (`user_id`),
  KEY `idx_login_attempts_identifier` (`email_or_mobile`),
  KEY `idx_login_attempts_time` (`attempted_at`),
  CONSTRAINT `FKtg9vhke4mlf5vij2rcvfk2dg2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
