--
-- Table structure for table `notification_log`
--

DROP TABLE IF EXISTS `notification_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `order_id` bigint DEFAULT NULL,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ORDER_PLACED, ORDER_CONFIRMED, ORDER_SHIPPED, ORDER_DELIVERED, ORDER_CANCELLED, NEW_ORDER_ADMIN, LOW_STOCK_ADMIN, WELCOME',
  `channel` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'EMAIL, WHATSAPP, IN_APP',
  `recipient` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Email address or E.164 phone number',
  `subject` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `read_at` datetime DEFAULT NULL COMMENT 'For IN_APP only: when the user read it',
  `sent_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_notif_log_order` (`order_id`),
  KEY `idx_notif_log_user_channel` (`user_id`,`channel`),
  KEY `idx_notif_log_user_unread` (`user_id`,`channel`,`read_at`),
  KEY `idx_notif_log_type` (`type`),
  KEY `idx_notif_log_created_at` (`created_at`),
  KEY `idx_notif_log_status` (`status`),
  CONSTRAINT `fk_notif_log_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_notif_log_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `notification_log`
--

LOCK TABLES `notification_log` WRITE;
/*!40000 ALTER TABLE `notification_log` DISABLE KEYS */;
